// app/preferences/page.tsx
"use client"

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/contexts/auth-context';
import authService from '@/services/auth.service';

interface Preference {
  id: number;
  name_fr: string;
  name_en: string;
  category: string;
  icon: string;
  description: string;
}

export default function PreferencesPage() {
  const router = useRouter();
  const { user } = useAuth();
  const [allPreferences, setAllPreferences] = useState<Preference[]>([]);
  const [selectedPreferences, setSelectedPreferences] = useState<number[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchPreferences();
  }, []);

  const fetchPreferences = async () => {
    try {
      // ✅ Utiliser authService qui ajoute automatiquement le token
      const data: any = await authService.getPreferences();
      
      console.log('✅ Préférences récupérées:', data);
      
      // Le backend peut retourner soit un tableau, soit un objet avec preferences
      if (Array.isArray(data)) {
        setAllPreferences(data);
      } else if (data && typeof data === 'object' && data.preferences && Array.isArray(data.preferences)) {
        setAllPreferences(data.preferences);
      } else {
        console.warn('⚠️ Format de réponse inattendu:', data);
        setError('Format de données invalide');
      }
      
    } catch (error: any) {
      console.error('❌ Erreur récupération préférences:', error);
      setError('Impossible de charger les préférences');
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePreference = (preferenceId: number) => {
    setSelectedPreferences(prev => {
      if (prev.includes(preferenceId)) {
        return prev.filter(id => id !== preferenceId);
      } else {
        return [...prev, preferenceId];
      }
    });
  };

  const handleSubmit = async () => {
    if (selectedPreferences.length === 0) {
      setError('Veuillez sélectionner au moins une préférence');
      return;
    }

    setSaving(true);
    setError(null);

    try {
      await authService.updatePreferences(selectedPreferences);
      console.log('✅ Préférences sauvegardées');
      router.push('/#hero');
      
    } catch (error: any) {
      console.error('❌ Erreur sauvegarde préférences:', error);
      setError('Erreur lors de la sauvegarde des préférences');
    } finally {
      setSaving(false);
    }
  };

  // Grouper les préférences par catégorie
  const groupedPreferences = allPreferences.reduce((acc, pref) => {
    if (!acc[pref.category]) {
      acc[pref.category] = [];
    }
    acc[pref.category].push(pref);
    return acc;
  }, {} as Record<string, Preference[]>);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#FF5722] mx-auto"></div>
          <p className="mt-4 text-gray-600">Chargement des préférences...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-2xl shadow-sm border border-gray-200 p-8">
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Parlez-nous de vous</h1>
            <p className="text-gray-600 mt-2">
              Sélectionnez vos préférences pour nous aider à vous mettre en relation avec les bons compagnons de voyage
            </p>
          </div>

          {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-600">
              {error}
            </div>
          )}

          {allPreferences.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-gray-500">Aucune préférence disponible</p>
              <p className="text-sm text-gray-400 mt-2">
                Vérifiez que des préférences existent dans la base de données
              </p>
            </div>
          ) : (
            <div className="space-y-8">
              {Object.entries(groupedPreferences).map(([category, prefs]) => (
                <div key={category}>
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">
                    {category === 'interests' && '🎯 Centres d\'intérêt'}
                    {category === 'habits' && '🔄 Habitudes'}
                    {category === 'driving' && '🚗 Préférences de conduite'}
                    {!['interests', 'habits', 'driving'].includes(category) && category}
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    {prefs.map((pref) => (
                      <button
                        key={pref.id}
                        onClick={() => handleTogglePreference(pref.id)}
                        className={`p-4 rounded-lg border-2 transition-all text-left ${
                          selectedPreferences.includes(pref.id)
                            ? 'border-[#FF5722] bg-[#FFF3F0]'
                            : 'border-gray-200 hover:border-gray-300'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          {pref.icon && <span className="text-2xl">{pref.icon}</span>}
                          <span className="font-medium text-gray-900">
                            {pref.name_fr || pref.name_en}
                          </span>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}

          <div className="mt-8 flex justify-between">
            <button
              onClick={() => router.push('/#hero')}
              className="px-6 py-3 text-gray-600 hover:text-gray-900"
            >
              Ignorer pour le moment
            </button>
            <button
              onClick={handleSubmit}
              disabled={saving || selectedPreferences.length === 0}
              className="px-8 py-3 bg-[#FF5722] hover:bg-[#E64A19] text-white font-medium rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {saving ? 'Sauvegarde...' : `Continuer (${selectedPreferences.length})`}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}